type Pin = {
  name: string;
  x: number;
  y: number;
  /** Label position relative to the pin. */
  label: { dx: number; dy: number; anchor: "start" | "end" | "middle" };
  home?: boolean;
};

const pins: Pin[] = [
  { name: "Frisco", x: 215, y: 92, label: { dx: 18, dy: 8, anchor: "start" } },
  { name: "Garland", x: 340, y: 282, label: { dx: -18, dy: 8, anchor: "end" } },
  { name: "Rockwall", x: 461, y: 267, label: { dx: 18, dy: 8, anchor: "start" } },
  { name: "Sunnyvale", x: 392, y: 375, label: { dx: -14, dy: -14, anchor: "end" } },
  { name: "Mesquite", x: 367, y: 398, label: { dx: -14, dy: 32, anchor: "end" } },
  { name: "Forney", x: 453, y: 414, label: { dx: 20, dy: 9, anchor: "start" }, home: true },
  { name: "Terrell", x: 585, y: 423, label: { dx: 18, dy: 8, anchor: "start" } },
  { name: "Crandall", x: 463, y: 510, label: { dx: 18, dy: 8, anchor: "start" } },
];

const forney = pins.find((pin) => pin.home)!;

export function ServiceAreaMap({ className = "" }: { className?: string }) {
  return (
    <div className={`overflow-hidden border border-line bg-coal ${className}`}>
      <svg
        viewBox="0 0 800 600"
        role="img"
        aria-labelledby="service-map-title"
        className="block h-auto w-full"
      >
        <title id="service-map-title">
          Map of the towns we serve east of Dallas, Texas: Forney (home base), Mesquite,
          Sunnyvale, Rockwall, Terrell, Crandall, Garland and Frisco.
        </title>

        {/* Faint grid */}
        <g stroke="var(--color-line)" strokeWidth="1">
          {[100, 200, 300, 400, 500, 600, 700].map((x) => (
            <line key={`v${x}`} x1={x} y1="0" x2={x} y2="600" />
          ))}
          {[100, 200, 300, 400, 500].map((y) => (
            <line key={`h${y}`} x1="0" y1={y} x2="800" y2={y} />
          ))}
        </g>

        {/* Spokes from home base */}
        <g stroke="var(--color-red)" strokeOpacity="0.45" strokeWidth="2" strokeDasharray="6 6">
          {pins
            .filter((pin) => !pin.home)
            .map((pin) => (
              <line key={pin.name} x1={forney.x} y1={forney.y} x2={pin.x} y2={pin.y} />
            ))}
        </g>

        {/* Dallas, for reference only */}
        <circle cx="233" cy="390" r="5" fill="var(--color-muted-faint)" />
        <text x="221" y="397" textAnchor="end" fontSize="20" fill="var(--color-muted-faint)">
          Dallas
        </text>

        {/* Town pins */}
        {pins.map((pin) => (
          <g key={pin.name}>
            {pin.home ? (
              <circle cx={pin.x} cy={pin.y} r="20" fill="var(--color-red)" fillOpacity="0.2" />
            ) : null}
            <circle
              cx={pin.x}
              cy={pin.y}
              r={pin.home ? 10 : 7}
              fill="var(--color-red)"
              stroke="var(--color-coal)"
              strokeWidth="3"
            />
            <text
              x={pin.x + pin.label.dx}
              y={pin.y + pin.label.dy}
              textAnchor={pin.label.anchor}
              fontSize="24"
              fontWeight="700"
              fill="var(--color-bone)"
            >
              {pin.name}
            </text>
          </g>
        ))}
        <text
          x={forney.x + 20}
          y={forney.y + 32}
          fontSize="14"
          fontWeight="700"
          letterSpacing="2"
          fill="var(--color-red-soft)"
        >
          HOME BASE
        </text>

        {/* Texas locator */}
        <rect x="606" y="12" width="182" height="172" fill="var(--color-ink)" stroke="var(--color-edge)" />
        <path d={TEXAS_PATH} fill="var(--color-coal)" stroke="var(--color-muted-faint)" strokeWidth="1.5" />
        <rect x="726" y="64" width="22" height="20" fill="var(--color-red)" fillOpacity="0.35" stroke="var(--color-red)" strokeWidth="2" />
        <text x="622" y="174" fontSize="13" fontWeight="700" letterSpacing="2" fill="var(--color-muted)">
          TEXAS
        </text>

        {/* Caption */}
        <text x="32" y="572" fontSize="20" fill="var(--color-muted)">
          Based in Forney, TX. We work within 60 miles.
        </text>
      </svg>
    </div>
  );
}
